do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4431,"word":"summon","meaning":"召喚","example":"The conductor used a small bell to summon the musicians to rehearsal.","example_zh":"指揮用小鈴召集樂手排練。","original_meaning":"召喚","original_example":"Summon a witness.","original_example_zh":"傳喚證人。"},{"source_id":4432,"word":"superstition","meaning":"迷信","example":"The story explored a superstition about a particular old tree.","example_zh":"故事探討與一棵老樹有關的迷信。","original_meaning":"迷信","original_example":"A common superstition.","original_example_zh":"一種常見的迷信。"},{"source_id":4433,"word":"surgeon","meaning":"外科醫生","example":"The surgeon explained the planned procedure to the patient.","example_zh":"外科醫師向病人說明規劃中的手術。","original_meaning":"外科醫生","original_example":"A brain surgeon.","original_example_zh":"腦外科醫師。"},{"source_id":4434,"word":"susceptibility","meaning":"易感性","example":"The gardeners compared the plants' susceptibility to frost.","example_zh":"園丁比較不同植物容易受霜害的程度。","original_meaning":"易感性","original_example":"Disease susceptibility.","original_example_zh":"易感性。"},{"source_id":4435,"word":"suspension","meaning":"暫停","example":"The storm caused a temporary suspension of the ferry service.","example_zh":"風暴使渡輪服務暫時停航。","original_meaning":"暫停","original_example":"A suspension of play.","original_example_zh":"比賽暫停。"},{"source_id":4436,"word":"sustenance","meaning":"營養；維生食物","example":"The hikers carried enough food for sustenance during the long walk.","example_zh":"健行者攜帶足夠食物，提供長程步行所需的營養。","original_meaning":"營養","original_example":"Seek sustenance.","original_example_zh":"尋求生計。"},{"source_id":4437,"word":"swamp","meaning":"沼澤","example":"The boardwalk allowed us to observe the swamp without disturbing it.","example_zh":"木棧道讓我們觀察沼澤，同時不干擾環境。","original_meaning":"沼澤","original_example":"A murky swamp.","original_example_zh":"一片渾濁的沼澤。"},{"source_id":4438,"word":"symmetry","meaning":"對稱","example":"The butterfly's wings showed striking symmetry.","example_zh":"蝴蝶雙翅展現鮮明對稱。","original_meaning":"對稱","original_example":"Perfect symmetry.","original_example_zh":"完美的對稱。"},{"source_id":4439,"word":"symptom","meaning":"症狀","example":"The patient described each symptom to the doctor.","example_zh":"病人向醫師描述每項症狀。","original_meaning":"症狀","original_example":"A sore throat was the first symptom, so I wore a mask at school.","original_example_zh":"喉嚨痛是第一個症狀，所以我在學校戴上口罩。"},{"source_id":4440,"word":"machinery","meaning":"機械","example":"The museum preserved machinery from the old textile mill.","example_zh":"博物館保存老紡織廠的機械。","original_meaning":"機械","original_example":"Heavy machinery.","original_example_zh":"重型機械。"},{"source_id":4441,"word":"magistracy","meaning":"地方司法官職；地方行政","example":"The museum explained the role of the magistracy in local justice.","example_zh":"博物館解說地方司法官職在地方司法中的角色。","original_meaning":"地方行政","original_example":"The local magistracy.","original_example_zh":"當地治安法庭。"},{"source_id":4442,"word":"maintenance","meaning":"維護","example":"Regular maintenance kept the bicycles safe to ride.","example_zh":"定期維護讓自行車保持騎乘安全。","original_meaning":"維護","original_example":"Equipment maintenance.","original_example_zh":"設備維護。"},{"source_id":4443,"word":"malady","meaning":"疾病","example":"The old diary described a malady that kept the traveler indoors.","example_zh":"老日記記述一場讓旅人留在室內休養的疾病。","original_meaning":"疾病","original_example":"A chronic malady.","original_example_zh":"慢性疾病。"},{"source_id":4444,"word":"manor","meaning":"莊園","example":"The old manor stood among gardens and farmland.","example_zh":"老莊園坐落於花園與農田之間。","original_meaning":"莊園","original_example":"An old manor.","original_example_zh":"一座古老的莊園。"},{"source_id":4445,"word":"maritime","meaning":"海事的","example":"The maritime museum displayed old navigation instruments.","example_zh":"海事博物館展示古老航海儀器。","original_meaning":"海事的","original_example":"Maritime law.","original_example_zh":"海事法。"},{"source_id":4446,"word":"marshal","meaning":"元帥","example":"The portrait showed a marshal in a formal military uniform.","example_zh":"肖像呈現一位穿正式軍服的元帥。","original_meaning":"元帥","original_example":"A fire marshal.","original_example_zh":"消防督察。"},{"source_id":4447,"word":"martyr","meaning":"烈士","example":"The memorial honored a martyr who died defending freedom.","example_zh":"紀念館向一位為捍衛自由而犧牲的烈士致敬。","original_meaning":"烈士","original_example":"A political martyr.","original_example_zh":"政治烈士。"},{"source_id":4448,"word":"masquerade","meaning":"假面舞會","example":"The theatre hosted a masquerade with music and elaborate costumes.","example_zh":"劇院舉辦有音樂與華麗服裝的假面舞會。","original_meaning":"假面舞會","original_example":"A masquerade ball.","original_example_zh":"化裝舞會。"},{"source_id":4449,"word":"materialism","meaning":"物質主義","example":"The novel questioned materialism through a character who valued friendship more than wealth.","example_zh":"小說透過重友情勝於財富的角色，質疑物質主義。","original_meaning":"物質主義","original_example":"Consumer materialism.","original_example_zh":"消費主義。"},{"source_id":4450,"word":"matrix","meaning":"矩陣","example":"The class represented the matrix with rows and columns of colored counters.","example_zh":"班上用彩色計數片的橫列與直行表示矩陣。","original_meaning":"矩陣","original_example":"A data matrix.","original_example_zh":"數據矩陣。"},{"source_id":4451,"word":"mayhem","meaning":"混亂","example":"A sudden gust created mayhem among the paper decorations.","example_zh":"突來陣風讓紙裝飾亂成一團。","original_meaning":"混亂","original_example":"Total mayhem.","original_example_zh":"一片混亂。"},{"source_id":4452,"word":"mediation","meaning":"調解","example":"The clubs resolved their disagreement through mediation.","example_zh":"社團透過調解解決分歧。","original_meaning":"調解","original_example":"Seek mediation.","original_example_zh":"尋求調解。"},{"source_id":4453,"word":"membrane","meaning":"膜","example":"The model showed a membrane surrounding the cell.","example_zh":"模型展示包圍細胞的膜。","original_meaning":"膜","original_example":"A cell membrane.","original_example_zh":"細胞膜。"},{"source_id":4454,"word":"memorandum","meaning":"備忘錄","example":"The director sent a memorandum about the new library schedule.","example_zh":"主管發出關於圖書館新時間安排的備忘錄。","original_meaning":"備忘錄","original_example":"Write a memorandum.","original_example_zh":"撰寫備忘錄。"},{"source_id":4455,"word":"menace","meaning":"威脅","example":"The unstable branch was a menace to people using the path.","example_zh":"不穩的樹枝威脅使用步道的人。","original_meaning":"威脅","original_example":"A growing menace.","original_example_zh":"日益嚴重的威脅。"},{"source_id":4456,"word":"metaphysics","meaning":"形上學","example":"The metaphysics seminar explored questions about existence and reality.","example_zh":"形上學研討課探究存在與實在的問題。","original_meaning":"形上學","original_example":"Study metaphysics.","original_example_zh":"研讀形而上學。"},{"source_id":4457,"word":"meteorology","meaning":"氣象學","example":"The meteorology lesson used clouds and air-pressure models.","example_zh":"氣象學課使用雲與氣壓模型。","original_meaning":"氣象學","original_example":"Study meteorology.","original_example_zh":"研讀氣象學。"},{"source_id":4458,"word":"metropolis","meaning":"大都市","example":"The train carried us into the busy metropolis.","example_zh":"火車載著我們進入繁忙大都市。","original_meaning":"大都市","original_example":"A bustling metropolis.","original_example_zh":"一座繁華的大都會。"},{"source_id":4459,"word":"microbiology","meaning":"微生物學","example":"The microbiology exhibit introduced the variety of microscopic life.","example_zh":"微生物學展覽介紹微小生命的多樣性。","original_meaning":"微生物學","original_example":"Study microbiology.","original_example_zh":"研讀微生物學。"},{"source_id":4460,"word":"militant","meaning":"激進的","example":"The group's militant stance left little room for compromise.","example_zh":"那個團體激進的立場幾乎沒有妥協空間。","original_meaning":"激進的","original_example":"A militant group.","original_example_zh":"一個武裝組織。"},{"source_id":4461,"word":"mimicry","meaning":"模仿；擬態","example":"The insect's mimicry of a leaf helped it blend into the plants.","example_zh":"昆蟲模仿葉子的擬態，幫牠融入植物。","original_meaning":"模仿","original_example":"Animal mimicry.","original_example_zh":"動物的擬態行為。"},{"source_id":4462,"word":"miniature","meaning":"微型的","example":"The miniature village contained tiny houses and bridges.","example_zh":"微型村莊包含小房屋與橋梁。","original_meaning":"微型的","original_example":"A miniature model.","original_example_zh":"一個微型模型。"},{"source_id":4463,"word":"misdemeanor","meaning":"輕罪","example":"The civics lesson compared a misdemeanor with a more serious offense.","example_zh":"公民課比較輕罪與較嚴重的犯罪。","original_meaning":"輕罪","original_example":"A minor misdemeanor.","original_example_zh":"一項輕微的違規行為。"},{"source_id":4464,"word":"missile","meaning":"飛彈","example":"The museum displayed a deactivated missile from a historic collection.","example_zh":"博物館展示歷史收藏中的停用飛彈。","original_meaning":"飛彈","original_example":"Launch a missile.","original_example_zh":"發射一枚飛彈。"},{"source_id":4465,"word":"moderation","meaning":"適度","example":"She enjoyed the rich dessert in moderation.","example_zh":"她適量享用濃郁甜點。","original_meaning":"適度","original_example":"In moderation.","original_example_zh":"適度地。"},{"source_id":4466,"word":"molecular","meaning":"分子的","example":"The molecular model showed how the atoms were connected.","example_zh":"分子模型顯示原子的連接方式。","original_meaning":"分子的","original_example":"Molecular biology.","original_example_zh":"分子生物學。"},{"source_id":4467,"word":"monarchy","meaning":"君主制","example":"The exhibit explained the role of a monarch in a monarchy.","example_zh":"展覽解說君主在君主制中的角色。","original_meaning":"君主制","original_example":"A constitutional monarchy.","original_example_zh":"君主立憲制。"},{"source_id":4468,"word":"monologue","meaning":"獨白","example":"The actor delivered a moving monologue on the quiet stage.","example_zh":"演員在寧靜舞臺上呈現感人獨白。","original_meaning":"獨白","original_example":"A dramatic monologue.","original_example_zh":"戲劇性獨白。"},{"source_id":4469,"word":"moratorium","meaning":"暫停","example":"The council declared a moratorium on new building near the wetland.","example_zh":"議會宣布暫停濕地附近的新建工程。","original_meaning":"暫停","original_example":"A debt moratorium.","original_example_zh":"債務暫緩償還。"},{"source_id":4470,"word":"morphology","meaning":"形態學","example":"The botany class compared the morphology of several leaves.","example_zh":"植物學課比較數種葉片的形態。","original_meaning":"形態學","original_example":"Plant morphology.","original_example_zh":"植物形態學。"},{"source_id":4471,"word":"mosaic","meaning":"馬賽克","example":"The students made a mosaic from small pieces of colored tile.","example_zh":"學生用小塊彩色磁磚製作馬賽克。","original_meaning":"馬賽克","original_example":"A Roman mosaic.","original_example_zh":"羅馬馬賽克。"},{"source_id":4472,"word":"motif","meaning":"主題；反覆圖案","example":"A leaf motif appeared throughout the artist's designs.","example_zh":"葉片圖案反覆出現在藝術家的設計中。","original_meaning":"主題","original_example":"A recurring motif.","original_example_zh":"反覆出現的主題。"},{"source_id":4473,"word":"mountainous","meaning":"多山的","example":"The mountainous region had narrow valleys and winding roads.","example_zh":"多山地區有狹窄山谷與蜿蜒道路。","original_meaning":"多山的","original_example":"Mountainous terrain.","original_example_zh":"山區地形。"},{"source_id":4474,"word":"mural","meaning":"壁畫","example":"The mural brightened the wall beside the school library.","example_zh":"壁畫讓學校圖書館旁牆面明亮起來。","original_meaning":"壁畫","original_example":"A colorful mural.","original_example_zh":"一幅色彩繽紛的壁畫。"},{"source_id":4475,"word":"mutiny","meaning":"叛變","example":"The historical novel described a mutiny aboard the ship.","example_zh":"歷史小說描寫船上發生的叛變。","original_meaning":"叛變","original_example":"A military mutiny.","original_example_zh":"軍事叛亂。"},{"source_id":4476,"word":"narcissism","meaning":"自戀","example":"The play criticized the ruler's narcissism and constant demand for praise.","example_zh":"戲劇批評統治者的自戀與不斷索求讚美。","original_meaning":"自戀","original_example":"Extreme narcissism.","original_example_zh":"極端的自戀。"},{"source_id":4477,"word":"nemesis","meaning":"天敵；宿敵","example":"In the novel, the detective finally faced his old nemesis.","example_zh":"小說中，偵探終於面對他的宿敵。","original_meaning":"天敵","original_example":"His political nemesis.","original_example_zh":"他的政治死對頭。"},{"source_id":4478,"word":"neurology","meaning":"神經學","example":"The neurology lecture explored how nerves carry signals.","example_zh":"神經學講座探討神經如何傳遞訊號。","original_meaning":"神經學","original_example":"Study neurology.","original_example_zh":"研讀神經學。"},{"source_id":4479,"word":"neutron","meaning":"中子","example":"The atomic model placed a neutron inside the nucleus.","example_zh":"原子模型把一顆中子放在原子核內。","original_meaning":"中子","original_example":"A neutron star.","original_example_zh":"中子星。"},{"source_id":4480,"word":"nihilism","meaning":"虛無主義","example":"The philosophy class debated the meaning of nihilism.","example_zh":"哲學課討論虛無主義的意義。","original_meaning":"虛無主義","original_example":"Philosophical nihilism.","original_example_zh":"哲學上的虛無主義。"},{"source_id":4481,"word":"nomenclature","meaning":"命名法","example":"The biologist explained the nomenclature used to classify the plants.","example_zh":"生物學家解說分類植物時使用的命名法。","original_meaning":"命名法","original_example":"Scientific nomenclature.","original_example_zh":"科學命名法。"},{"source_id":4482,"word":"nostalgia","meaning":"懷舊","example":"The old school photographs filled her with nostalgia.","example_zh":"老校園照片讓她充滿懷舊之情。","original_meaning":"懷舊","original_example":"A feeling of nostalgia.","original_example_zh":"一股懷舊之情。"},{"source_id":4483,"word":"novice","meaning":"新手","example":"The novice learned to hold the violin with guidance from the teacher.","example_zh":"新手在老師指導下學習持琴。","original_meaning":"新手","original_example":"A complete novice.","original_example_zh":"一個完全的新手。"},{"source_id":4484,"word":"nucleus","meaning":"原子核","example":"The model showed the nucleus at the center of the atom.","example_zh":"模型展示原子中心的原子核。","original_meaning":"原子核","original_example":"A cell nucleus.","original_example_zh":"細胞核。"},{"source_id":4485,"word":"obituary","meaning":"訃聞","example":"The newspaper published an obituary honoring the retired teacher.","example_zh":"報紙刊登訃聞，紀念退休老師。","original_meaning":"訃聞","original_example":"Read the obituary.","original_example_zh":"閱讀訃聞。"},{"source_id":4486,"word":"oligarch","meaning":"寡頭","example":"The story's oligarch controlled several of the kingdom's largest businesses.","example_zh":"故事中的寡頭掌控王國數家最大企業。","original_meaning":"寡頭","original_example":"A Russian oligarch.","original_example_zh":"一位俄羅斯寡頭。"},{"source_id":4487,"word":"ombudsman","meaning":"監察使","example":"The ombudsman listened to residents' complaints about public services.","example_zh":"監察使聆聽居民對公共服務的申訴。","original_meaning":"監察使","original_example":"The national ombudsman.","original_example_zh":"國家申訴專員。"},{"source_id":4488,"word":"onslaught","meaning":"猛攻","example":"The stone wall withstood the onslaught of the waves.","example_zh":"石牆承受住海浪猛攻。","original_meaning":"猛攻","original_example":"An enemy onslaught.","original_example_zh":"敵人的猛攻。"},{"source_id":4489,"word":"opera","meaning":"歌劇","example":"The students attended an opera at the historic theatre.","example_zh":"學生在歷史劇院欣賞歌劇。","original_meaning":"歌劇","original_example":"Watch an opera.","original_example_zh":"觀賞歌劇。"},{"source_id":4490,"word":"oppressor","meaning":"壓迫者","example":"The novel portrayed villagers resisting an unfair oppressor.","example_zh":"小說描繪村民反抗不公壓迫者。","original_meaning":"壓迫者","original_example":"Fight the oppressor.","original_example_zh":"對抗壓迫者。"},{"source_id":4491,"word":"oracle","meaning":"神諭","example":"The ancient tale centered on an oracle about the kingdom's future.","example_zh":"古老故事圍繞關於王國未來的神諭展開。","original_meaning":"神諭","original_example":"Consult the oracle.","original_example_zh":"諮詢神諭。"},{"source_id":4492,"word":"orchestrate","meaning":"策劃","example":"The volunteers helped orchestrate the school reading festival.","example_zh":"志工協助策劃學校閱讀節。","original_meaning":"策劃","original_example":"Orchestrate a campaign.","original_example_zh":"策劃一場運動。"},{"source_id":4493,"word":"ordnance","meaning":"軍械","example":"The museum stored the historic ordnance in a secure exhibit.","example_zh":"博物館把歷史軍械保存在安全展區。","original_meaning":"軍械","original_example":"Military ordnance.","original_example_zh":"軍用彈藥。"},{"source_id":4494,"word":"orphan","meaning":"孤兒","example":"The story followed an orphan who found a caring community.","example_zh":"故事敘述一位孤兒找到關懷自己的社群。","original_meaning":"孤兒","original_example":"An orphaned child.","original_example_zh":"一名孤兒。"},{"source_id":4495,"word":"orthodoxy","meaning":"正統；主流看法","example":"The scholar questioned the prevailing orthodoxy about the painting's origin.","example_zh":"學者質疑關於畫作來源的主流正統看法。","original_meaning":"正統","original_example":"Religious orthodoxy.","original_example_zh":"宗教正統。"},{"source_id":4496,"word":"oscillation","meaning":"振盪","example":"The pendulum's oscillation gradually slowed.","example_zh":"鐘擺振盪逐漸減慢。","original_meaning":"振盪","original_example":"Electromagnetic oscillation.","original_example_zh":"電磁振盪。"},{"source_id":4497,"word":"osmosis","meaning":"滲透；滲透作用","example":"The biology model demonstrated osmosis across a semipermeable membrane.","example_zh":"生物模型展示水透過半透膜的滲透作用。","original_meaning":"滲透","original_example":"Water osmosis.","original_example_zh":"水滲透。"},{"source_id":4498,"word":"oust","meaning":"驅逐；罷免","example":"The committee voted to oust the dishonest treasurer.","example_zh":"委員會投票罷免不誠實的財務主管。","original_meaning":"驅逐","original_example":"Oust the leader.","original_example_zh":"罷黜領導人。"},{"source_id":4499,"word":"outcast","meaning":"被排斥者","example":"The story's outcast found friendship in the village library.","example_zh":"故事中被排斥的人在村莊圖書館找到友誼。","original_meaning":"被排斥者","original_example":"A social outcast.","original_example_zh":"社會邊緣人。"},{"source_id":4500,"word":"outlaw","meaning":"罪犯","example":"The historical novel followed an outlaw who eventually faced trial.","example_zh":"歷史小說敘述一位罪犯最終接受審判。","original_meaning":"罪犯","original_example":"An infamous outlaw.","original_example_zh":"臭名昭著的亡命之徒。"},{"source_id":4501,"word":"outskirts","meaning":"郊區；外圍","example":"The new garden lay on the outskirts of the town.","example_zh":"新花園位於城鎮外圍。","original_meaning":"郊區","original_example":"On the outskirts.","original_example_zh":"在郊區。"},{"source_id":4502,"word":"vacancy","meaning":"空缺","example":"The museum advertised a vacancy for a guide.","example_zh":"博物館徵求一位導覽員補足職缺。","original_meaning":"空缺","original_example":"Fill the vacancy.","original_example_zh":"填補空缺。"},{"source_id":4503,"word":"vaccine","meaning":"疫苗","example":"The medical museum traced the development of a vaccine.","example_zh":"醫學博物館追溯一種疫苗的研發。","original_meaning":"疫苗","original_example":"Develop a vaccine.","original_example_zh":"研發疫苗。"},{"source_id":4504,"word":"vagrant","meaning":"流浪者","example":"The novel described a vagrant who found shelter during the winter.","example_zh":"小說描寫一位流浪者在冬天找到庇護處。","original_meaning":"流浪者","original_example":"A homeless vagrant.","original_example_zh":"一名無家可歸的流浪漢。"},{"source_id":4505,"word":"valor","meaning":"英勇","example":"The award recognized the rescue worker's valor during the flood.","example_zh":"獎項表揚救援人員在洪災中的英勇。","original_meaning":"英勇","original_example":"An act of valor.","original_example_zh":"英勇之舉。"},{"source_id":4506,"word":"valve","meaning":"閥門","example":"The technician turned the valve to stop the water flow.","example_zh":"技術人員轉動閥門，停止水流。","original_meaning":"閥門","original_example":"A heart valve.","original_example_zh":"心臟瓣膜。"},{"source_id":4507,"word":"vandalism","meaning":"破壞公物","example":"The volunteers repaired the damage caused by vandalism in the park.","example_zh":"志工修復公園遭破壞公物後留下的損壞。","original_meaning":"破壞公物","original_example":"An act of vandalism.","original_example_zh":"破壞公物。"},{"source_id":4508,"word":"vein","meaning":"靜脈","example":"The anatomy model showed a vein carrying blood toward the heart.","example_zh":"解剖模型展示靜脈把血液帶向心臟。","original_meaning":"靜脈","original_example":"Blood in the veins.","original_example_zh":"血管中的血液。"},{"source_id":4509,"word":"velocity","meaning":"速度","example":"The sensor measured the cart's velocity along the straight track.","example_zh":"感測器測量推車沿直軌行進的速度。","original_meaning":"速度","original_example":"High velocity.","original_example_zh":"高速。"},{"source_id":4510,"word":"vendor","meaning":"攤販","example":"The vendor arranged fresh fruit at the market stall.","example_zh":"攤販在市集攤位擺放新鮮水果。","original_meaning":"攤販","original_example":"A street vendor.","original_example_zh":"一名街頭小販。"},{"source_id":4511,"word":"ventilate","meaning":"通風","example":"The staff opened the high windows to ventilate the hall.","example_zh":"工作人員打開高窗，讓禮堂通風。","original_meaning":"通風","original_example":"Ventilate the room.","original_example_zh":"通風換氣。"},{"source_id":4512,"word":"venue","meaning":"場地","example":"The library garden was chosen as the venue for the concert.","example_zh":"圖書館花園獲選為音樂會場地。","original_meaning":"場地","original_example":"A concert venue.","original_example_zh":"一個音樂會場地。"},{"source_id":4513,"word":"vertebrate","meaning":"脊椎動物","example":"The exhibit classified the frog as a vertebrate.","example_zh":"展覽把青蛙歸為脊椎動物。","original_meaning":"脊椎動物","original_example":"Fish are vertebrates.","original_example_zh":"魚類是脊椎動物。"},{"source_id":4514,"word":"vessel","meaning":"船隻","example":"The research vessel carried scientists along the coast.","example_zh":"研究船載科學家沿海岸航行。","original_meaning":"船隻","original_example":"A cargo vessel.","original_example_zh":"一艘貨輪。"},{"source_id":4515,"word":"veteran","meaning":"老兵","example":"The veteran shared memories of rebuilding the town after the war.","example_zh":"老兵分享戰後重建城鎮的回憶。","original_meaning":"老兵","original_example":"A war veteran.","original_example_zh":"一位退伍軍人。"},{"source_id":4516,"word":"vicinity","meaning":"附近","example":"Several quiet paths lay in the vicinity of the museum.","example_zh":"博物館附近有幾條安靜步道。","original_meaning":"附近","original_example":"In the vicinity.","original_example_zh":"在附近。"},{"source_id":4517,"word":"vigor","meaning":"活力","example":"The students approached the new project with vigor.","example_zh":"學生充滿活力地投入新專案。","original_meaning":"活力","original_example":"Full of vigor.","original_example_zh":"充滿活力。"},{"source_id":4518,"word":"villa","meaning":"別墅","example":"The old villa overlooked the blue lake.","example_zh":"老別墅俯瞰藍色湖泊。","original_meaning":"別墅","original_example":"A vacation villa.","original_example_zh":"一棟度假別墅。"},{"source_id":4519,"word":"villager","meaning":"村民","example":"The villager showed the visitors how to weave a basket.","example_zh":"村民向訪客示範編籃。","original_meaning":"村民","original_example":"A local villager.","original_example_zh":"一位當地村民。"},{"source_id":4520,"word":"vindictive","meaning":"報復的","example":"The vindictive character plotted revenge after losing the contest.","example_zh":"那位懷報復心的角色輸掉比賽後策劃報復。","original_meaning":"報復的","original_example":"A vindictive person.","original_example_zh":"一個心懷怨恨的人。"},{"source_id":4521,"word":"vintage","meaning":"經典的","example":"The museum displayed a vintage camera in excellent condition.","example_zh":"博物館展示一臺保存良好的經典老相機。","original_meaning":"經典的","original_example":"A vintage car.","original_example_zh":"一輛古董車。"},{"source_id":4522,"word":"violin","meaning":"小提琴","example":"She practiced the violin before the school concert.","example_zh":"學校音樂會前，她練習小提琴。","original_meaning":"小提琴","original_example":"Play the violin.","original_example_zh":"拉小提琴。"},{"source_id":4523,"word":"visa","meaning":"簽證","example":"The traveler checked the visa in her passport before the journey.","example_zh":"旅人出發前查看護照裡的簽證。","original_meaning":"簽證","original_example":"Apply for a visa.","original_example_zh":"申請簽證。"},{"source_id":4524,"word":"visceral","meaning":"內臟的","example":"The anatomy lesson examined visceral organs in a teaching model.","example_zh":"解剖課檢視教學模型裡的內臟器官。","original_meaning":"內臟的","original_example":"A visceral reaction.","original_example_zh":"本能的反應。"},{"source_id":4525,"word":"vocational","meaning":"職業的","example":"The vocational course taught practical woodworking skills.","example_zh":"職業課程教授實用木工技能。","original_meaning":"職業的","original_example":"Vocational training.","original_example_zh":"職業培訓。"},{"source_id":4526,"word":"void","meaning":"空虛","example":"The sudden departure left a void in the close-knit group.","example_zh":"突然離別讓緊密團體感到空虛。","original_meaning":"空虛","original_example":"A moral void.","original_example_zh":"道德真空。"},{"source_id":4527,"word":"volcanic","meaning":"火山的","example":"The geologist showed us a volcanic rock full of small holes.","example_zh":"地質學家向我們展示多孔火山岩。","original_meaning":"火山的","original_example":"Volcanic eruption.","original_example_zh":"火山爆發。"},{"source_id":4528,"word":"voltage","meaning":"電壓","example":"The students measured the voltage of a small battery.","example_zh":"學生測量小電池的電壓。","original_meaning":"電壓","original_example":"High voltage.","original_example_zh":"高電壓。"},{"source_id":4529,"word":"voluntary","meaning":"自願的","example":"Participation in the weekend cleanup was voluntary.","example_zh":"參加週末清潔活動完全出於自願。","original_meaning":"自願的","original_example":"Voluntary service.","original_example_zh":"志願服務。"},{"source_id":4530,"word":"voucher","meaning":"兌換券","example":"The students exchanged a voucher for books at the fair.","example_zh":"學生在書展用兌換券換書。","original_meaning":"兌換券","original_example":"A gift voucher.","original_example_zh":"禮品券。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-summon-01-v1","level":"senior","word":"summon","sort_order":1,"sense":"召喚","alt_zh":"成年指揮在學校音樂室門口搖小鈴，高中樂手拿樂器集合。","example":"The conductor used a small bell to summon the musicians to rehearsal.","example_zh":"指揮用小鈴召集樂手排練。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/summon-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-superstition-01-v1","level":"senior","word":"superstition","sort_order":1,"sense":"迷信","alt_zh":"高中生在圖書館聽成年導覽員介紹地方傳說，桌上有老樹插畫，無恐怖或嘲弄文化。","example":"The story explored a superstition about a particular old tree.","example_zh":"故事探討與一棵老樹有關的迷信。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/superstition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-surgeon-01-v1","level":"senior","word":"surgeon","sort_order":1,"sense":"外科醫生","alt_zh":"成年外科醫師在明亮診間向成年病人展示無字教學模型，無手術傷口或操作步驟。","example":"The surgeon explained the planned procedure to the patient.","example_zh":"外科醫師向病人說明規劃中的手術。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/surgeon-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-susceptibility-01-v1","level":"senior","word":"susceptibility","sort_order":1,"sense":"易感性","alt_zh":"成年園丁與高中生在溫室觀察一盆霜傷葉片與一盆耐寒植物，無藥劑。","example":"The gardeners compared the plants' susceptibility to frost.","example_zh":"園丁比較不同植物容易受霜害的程度。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/susceptibility-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-suspension-01-v1","level":"senior","word":"suspension","sort_order":1,"sense":"暫停","alt_zh":"安全港口中民用渡輪繫泊，成年工作人員引導旅客在乾燥候船室等候。","example":"The storm caused a temporary suspension of the ferry service.","example_zh":"風暴使渡輪服務暫時停航。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/suspension-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-sustenance-01-v1","level":"senior","word":"sustenance","sort_order":1,"sense":"營養；維生食物","alt_zh":"成年嚮導與高中生在安全健行休息點整理足夠水壺、麵包與水果。","example":"The hikers carried enough food for sustenance during the long walk.","example_zh":"健行者攜帶足夠食物，提供長程步行所需的營養。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/sustenance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-swamp-01-v1","level":"senior","word":"swamp","sort_order":1,"sense":"沼澤","alt_zh":"高中生與成年自然老師沿有護欄木棧道觀察沼澤植被、鳥類與靜水。","example":"The boardwalk allowed us to observe the swamp without disturbing it.","example_zh":"木棧道讓我們觀察沼澤，同時不干擾環境。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/swamp-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-symmetry-01-v1","level":"senior","word":"symmetry","sort_order":1,"sense":"對稱","alt_zh":"高中生在自然館觀察張開雙翅、左右花紋對稱的蝴蝶模型，無傷害動物。","example":"The butterfly's wings showed striking symmetry.","example_zh":"蝴蝶雙翅展現鮮明對稱。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/symmetry-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-symptom-01-v1","level":"senior","word":"symptom","sort_order":1,"sense":"症狀","alt_zh":"成年病人在安靜診間與成年醫師耐心交談，桌上有無字筆記，無診斷或醫療指示。","example":"The patient described each symptom to the doctor.","example_zh":"病人向醫師描述每項症狀。","image_url":"https://jbspxqebcrkilfcddluo.supabase.